cd /tmp/wtest && cat > probe4.py <<'EOF'
import socket, threading, subprocess, time

BIN = "/workspace/artifacts/target/busybox"
MAX_REDIRECTS = 40

def run(redirect_count, label, loc_fmt="http://127.0.0.1:{port}/r{n}", timeout=10):
    """Serve up to redirect_count sequential connections, each returning a redirect."""
    s = socket.socket()
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("127.0.0.1", 0)); s.listen(8)
    port = s.getsockname()[1]
    count = {"n": 0}
    stop = {"stop": False}
    def serve():
        while not stop["stop"] and count["n"] < redirect_count + 5:
            try:
                s.settimeout(3)
                conn, _ = s.accept()
            except Exception:
                return
            count["n"] += 1
            n = count["n"]
            try:
                conn.settimeout(3)
                data = b""
                try:
                    while b"\r\n\r\n" not in data:
                        d = conn.recv(4096)
                        if not d: break
                        data += d
                except Exception: pass
                if n <= redirect_count:
                    loc = loc_fmt.format(port=port, n=n).encode()
                    resp = b"HTTP/1.1 302 Found\r\nLocation: " + loc + b"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                else:
                    resp = b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nhi"
                try:
                    conn.sendall(resp)
                except Exception: pass
                try: conn.close()
                except Exception: pass
            except Exception:
                pass
    t = threading.Thread(target=serve, daemon=True); t.start()
    url = f"http://127.0.0.1:{port}/start"
    try:
        r = subprocess.run([BIN, "wget", "-O", "/tmp/wtest/o.bin", url], capture_output=True, text=True, timeout=timeout)
        rc, se, so, to = r.returncode, r.stderr, r.stdout, False
    except subprocess.TimeoutExpired:
        rc, se, so, to = None, "TIMEOUT", "", True
    stop["stop"] = True
    try: s.close()
    except: pass
    t.join(1)
    print(f"--- {label}: rc={rc} to={to} conns={count['n']}")
    if se: print("  ERR:", se[:300].replace("\n","\\n"))

run(5, "5-redirects")
run(50, "50-redirects")
